    public init(
        requirementId: String,
        reason: SimulationOnboardingCoverageGapDtoReason,
        detail: String? = nil,
        additionalProperties: [String: JSONValue] = .init()
    ) {
        self.requirementId = requirementId
        self.reason = reason
        self.detail = detail
        self.additionalProperties = additionalProperties
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.requirementId = try container.decode(String.self, forKey: .requirementId)
        self.reason = try container.decode(SimulationOnboardingCoverageGapDtoReason.self, forKey: .reason)
        self.detail = try container.decodeIfPresent(String.self, forKey: .detail)
        self.additionalProperties = try decoder.decodeAdditionalProperties(using: CodingKeys.self)
    }

    public func encode(to encoder: Encoder) throws -> Void {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try encoder.encodeAdditionalProperties(self.additionalProperties)
        try container.encode(self.requirementId, forKey: .requirementId)
        try container.encode(self.reason, forKey: .reason)
        try container.encodeIfPresent(self.detail, forKey: .detail)
    }

    /// Keys for encoding/decoding struct properties.
    enum CodingKeys: String, CodingKey, CaseIterable {
        case requirementId
        case reason
        case detail
    }
}